165	export type SettlementByMethod = { method: string; amount: number };
166	
167	export type SettlementTicketInput = {
168	  businessName: string;
169	  periodLabel: string;
170	  byMethod: SettlementByMethod[];
171	  totalSales: number;
172	  txCount: number;
173	  voidCount: number;
174	};
