176	// Ringkasan penjualan per metode bayar (Tunai/QRIS/EDC/dst) — dicetak dari
177	// Halaman Laporan atau langsung setelah tutup shift. Beda dari
178	// buildReceiptTicket: ini rekap banyak transaksi dalam satu rentang
179	// tanggal, bukan satu struk.
180	export function buildSettlementTicket(input: SettlementTicketInput): Buffer {
181	  const chunks: Buffer[] = [];
182	  const push = (bytes: number[]) => chunks.push(Buffer.from(bytes));
183	  const text = (s: string) => chunks.push(Buffer.from(`${s}\n`, "latin1"));
184	  const divider = () => text("-".repeat(RECEIPT_WIDTH));
185	
186	  push([ESC, 0x40]); // initialize
187	
188	  push([ESC, 0x61, 0x01]); // center align
189	  text(input.businessName.toUpperCase());
190	  text("LAPORAN SETTLEMENT");
191	  push([ESC, 0x61, 0x00]); // left align
192	
193	  divider();
194	  text(padLine("Periode", input.periodLabel));
195	  text(padLine("Dicetak", new Date().toLocaleString("id-ID")));
196	
197	  divider();
198	  if (input.byMethod.length === 0) {
199	    text("Tidak ada transaksi.");
200	  } else {
201	    for (const m of input.byMethod) {
202	      text(padLine(m.method, formatRp(m.amount)));
203	    }
204	  }
205	  push([ESC, 0x45, 0x01]);
206	  text(padLine("TOTAL", formatRp(input.totalSales)));
207	  push([ESC, 0x45, 0x00]);
208	
209	  divider();
210	  text(padLine("Jumlah Transaksi", String(input.txCount)));
211	  if (input.voidCount > 0) text(padLine("Dibatalkan", String(input.voidCount)));
212	
213	  text("");
214	  text("");
215	  push([GS, 0x56, 0x42, 0x00]); // partial cut with feed
216	
217	  return Buffer.concat(chunks);
218	}
