230	// Rekap menu terjual (nama/qty/omzet) untuk rentang tanggal — urutan sudah
231	// diasumsikan sesuai keinginan pemanggil (mis. by omzet desc, sama seperti
232	// "Menu Terlaris" di Halaman Laporan).
233	export function buildMenuSalesTicket(input: MenuSalesTicketInput): Buffer {
234	  const chunks: Buffer[] = [];
235	  const push = (bytes: number[]) => chunks.push(Buffer.from(bytes));
236	  const text = (s: string) => chunks.push(Buffer.from(`${s}\n`, "latin1"));
237	  const divider = () => text("-".repeat(RECEIPT_WIDTH));
238	
239	  push([ESC, 0x40]); // initialize
240	
241	  push([ESC, 0x61, 0x01]); // center align
242	  text(input.businessName.toUpperCase());
243	  text("LAPORAN PENJUALAN MENU");
244	  push([ESC, 0x61, 0x00]); // left align
245	
246	  divider();
247	  text(padLine("Periode", input.periodLabel));
248	  text(padLine("Dicetak", new Date().toLocaleString("id-ID")));
249	
250	  divider();
251	  if (input.items.length === 0) {
252	    text("Tidak ada transaksi.");
253	  } else {
254	    for (const item of input.items) {
255	      text(truncate(item.name));
256	      text(padLine(`  ${formatQty(item.qty)}x`, formatRp(item.amount)));
257	    }
258	  }
259	
260	  divider();
261	  text(padLine("Total Qty", formatQty(input.totalQty)));
262	  push([ESC, 0x45, 0x01]);
263	  text(padLine("TOTAL", formatRp(input.totalAmount)));
264	  push([ESC, 0x45, 0x00]);
265	
266	  text("");
267	  text("");
268	  push([GS, 0x56, 0x42, 0x00]); // partial cut with feed
269	
270	  return Buffer.concat(chunks);
271	}
